import{_ as t,o,c as d,a2 as a}from"./chunks/framework.DYPTBNgj.js";const u=JSON.parse('{"title":"Workflow File Format","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflow-file-format.md","filePath":"reference/workflow-file-format.md"}'),r={name:"reference/workflow-file-format.md"};function n(s,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="workflow-file-format" tabindex="-1">Workflow File Format <a class="header-anchor" href="#workflow-file-format" aria-label="Permalink to &quot;Workflow File Format&quot;">​</a></h1><p>This page documents the JSON shape of a workflow: every top-level field, what a node and a connection look like on the wire, and which fields are required. It assumes you already know what a workflow, node, and connection are; see <a href="./../getting-started/concepts">Concepts</a> first if not.</p><h2 id="the-file-itself" tabindex="-1">The file itself <a class="header-anchor" href="#the-file-itself" aria-label="Permalink to &quot;The file itself&quot;">​</a></h2><p>A workflow is plain JSON, saved with a <code>.aerini</code> extension by convention. A <code>.json</code> file with the same shape works the same way, see <a href="./../glossary#workflow-file">Workflow file</a>. This is the shape Aerini&#39;s own database stores, the shape exchanged between the desktop frontend and the engine, and the shape the scheduler loads for a background run.</p><h2 id="json-schema" tabindex="-1">JSON Schema <a class="header-anchor" href="#json-schema" aria-label="Permalink to &quot;JSON Schema&quot;">​</a></h2><p>A JSON Schema (draft 2020-12) for this shape is generated from the engine&#39;s own types and kept in the repository as <code>docs/reference/workflow.schema.json</code>. Use it to check a hand-written or generated file before you import it. It checks field names, value types, and which fields are required, the same things the tables below describe. It does not check that a <code>node_type_id</code> exists, that a node&#39;s <code>config</code> is valid for that node, or that connections fit a node&#39;s ports; the <a href="./node-catalog">Node Catalog</a> lists what each node accepts. The schema describes the current <a href="#schema-version">schema version</a>.</p><h2 id="top-level-fields" tabindex="-1">Top-level fields <a class="header-anchor" href="#top-level-fields" aria-label="Permalink to &quot;Top-level fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default / notes</th></tr></thead><tbody><tr><td><code>schema_version</code></td><td>string</td><td>No</td><td>See <a href="#schema-version">Schema version</a> below.</td></tr><tr><td><code>id</code></td><td>string</td><td>Yes</td><td>Unique ID for this workflow.</td></tr><tr><td><code>name</code></td><td>string</td><td>Yes</td><td>Display name shown in the Workflows sidebar and window title.</td></tr><tr><td><code>description</code></td><td>string</td><td>No</td><td>Defaults to an empty string. Not currently editable from the desktop UI; present in the schema for hand-authored or generated files.</td></tr><tr><td><code>nodes</code></td><td>array of <a href="#nodes">node objects</a></td><td>Yes</td><td>Every box on the canvas, including trigger nodes.</td></tr><tr><td><code>edges</code></td><td>array of <a href="#connections">connection objects</a></td><td>Yes</td><td>Called a &quot;connection&quot; everywhere else in these docs; the JSON key is <code>edges</code>.</td></tr><tr><td><code>metadata</code></td><td>object</td><td>No</td><td>Defaults per field if omitted, see <a href="#metadata">Metadata</a> below.</td></tr><tr><td><code>max_duration_secs</code></td><td>number</td><td>No</td><td>Wall-clock limit for the whole run, in seconds. The executor clamps any value to the 10 to 86400 range. Omit for no limit.</td></tr><tr><td><code>unlimited_duration</code></td><td>boolean</td><td>No</td><td>Defaults to <code>false</code>. Only takes effect on a manual run started from the desktop app; scheduled and background runs never read this field. When <code>true</code>, the run ignores both the server&#39;s duration ceiling and this workflow&#39;s own <code>max_duration_secs</code>.</td></tr><tr><td><code>parallel_execution</code></td><td>boolean</td><td>No</td><td>Defaults to <code>false</code>. When <code>true</code>, independent branches run concurrently instead of one after another.</td></tr><tr><td><code>max_concurrent_nodes</code></td><td>number</td><td>No</td><td>Caps simultaneous node tasks when <code>parallel_execution</code> is <code>true</code>. Falls back to 8 if unset.</td></tr><tr><td><code>settings</code></td><td>object</td><td>No</td><td>Currently holds only <code>chat</code>, see <a href="#chat-settings">Chat settings</a> below.</td></tr><tr><td><code>annotations</code></td><td>array of <a href="#annotations">annotation objects</a></td><td>No</td><td>Defaults to <code>[]</code> and is left out of a saved file when empty. Sticky notes and group frames drawn on the canvas; the engine never runs them. At most 500 are kept.</td></tr></tbody></table><h3 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h3><p>An annotation is a sticky note or a group frame drawn on the canvas. It has no ports, never runs and never appears in <code>nodes</code>. A workflow saved before annotations existed, or by an older build, simply has none.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default / notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Yes</td><td>Unique ID within the workflow.</td></tr><tr><td><code>kind</code></td><td>string</td><td>No</td><td><code>&quot;note&quot;</code> (default) or <code>&quot;frame&quot;</code>, a titled box for labelling a group of nodes. An entry with any other <code>kind</code> is skipped when the file is opened.</td></tr><tr><td><code>x</code>, <code>y</code></td><td>number</td><td>Yes</td><td>Top-left corner on the canvas.</td></tr><tr><td><code>w</code></td><td>number</td><td>No</td><td>Width in canvas units. Absent means the default for the kind.</td></tr><tr><td><code>h</code></td><td>number</td><td>No</td><td>Height in canvas units. Absent means a note grows to fit its text; a frame uses a default height.</td></tr><tr><td><code>text</code></td><td>string</td><td>No</td><td>A note&#39;s text, up to 10 000 characters (longer text is cut). <code>**bold**</code>, <code>[label](https://…)</code> links, <code>- [ ]</code> / <code>- [x]</code> checkbox lines and a leading <code># </code> heading are drawn; nothing else is interpreted.</td></tr><tr><td><code>title</code></td><td>string</td><td>No</td><td>A frame&#39;s title, up to 120 characters (longer text is cut). A frame has no <code>text</code>.</td></tr><tr><td><code>color</code></td><td>string</td><td>No</td><td><code>default</code>, <code>yellow</code>, <code>blue</code>, <code>green</code> or <code>red</code>. Any other value is shown as <code>default</code>.</td></tr><tr><td><code>size</code></td><td>string</td><td>No</td><td>Text size: <code>s</code>, <code>m</code>, <code>l</code> or <code>xl</code>. Absent, or any other value, is shown as <code>m</code>. A note&#39;s size applies to its text, a frame&#39;s to its title.</td></tr></tbody></table><p>Extra annotations beyond 500 are dropped and over-long text is cut rather than rejected, so saving never fails because of a note. A workflow whose <code>nodes</code> list still holds an old <code>note</code> entry is read as an annotation.</p><h3 id="metadata" tabindex="-1">Metadata <a class="header-anchor" href="#metadata" aria-label="Permalink to &quot;Metadata&quot;">​</a></h3><p>The <code>metadata</code> object as a whole is optional: leave it out entirely and every field below falls back to its default. Include it, though, and <code>author</code>, <code>created_at</code>, and <code>updated_at</code> are required inside it; only <code>tags</code> and <code>collection_id</code> keep their own per-field defaults regardless.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default when <code>metadata</code> is absent</th></tr></thead><tbody><tr><td><code>author</code></td><td>string</td><td><code>&quot;user&quot;</code></td></tr><tr><td><code>created_at</code></td><td>string, ISO-8601</td><td>current time</td></tr><tr><td><code>updated_at</code></td><td>string, ISO-8601</td><td>current time</td></tr><tr><td><code>version</code></td><td>string</td><td><code>&quot;1.0.0&quot;</code>. A free-form label, not the same field as the top-level <code>schema_version</code>.</td></tr><tr><td><code>tags</code></td><td>array of strings</td><td><code>[]</code></td></tr><tr><td><code>collection_id</code></td><td>string or <code>null</code></td><td><code>null</code></td></tr></tbody></table><p><code>collection_id</code> references a named collection in the Workflows sidebar by ID. The collection&#39;s own name and color live outside the workflow file; a missing or <code>null</code> <code>collection_id</code> leaves the workflow Uncategorized.</p><p>The desktop app cleans <code>tags</code> when it opens a workflow: entries that are not strings or are empty after trimming are dropped, tags that differ only by letter case count as one (the first spelling is kept), a tag is cut to 32 characters, and only the first 20 are kept. The file on disk is not rewritten until the workflow is saved.</p><h3 id="chat-settings" tabindex="-1">Chat settings <a class="header-anchor" href="#chat-settings" aria-label="Permalink to &quot;Chat settings&quot;">​</a></h3><p><code>settings.chat</code> mirrors the Chat Panel toggles set from the Workflow Settings modal. Each field defaults independently, so a file that sets only some of them still loads correctly. See <a href="./../guide/chat-panel">Chat Panel</a> for what each toggle actually does in the app.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>allow_attachments</code></td><td>boolean</td><td><code>false</code></td></tr><tr><td><code>allow_image_responses</code></td><td>boolean</td><td><code>true</code></td></tr><tr><td><code>max_message_length</code></td><td>number</td><td><code>2000</code></td></tr><tr><td><code>session_persistence</code></td><td>boolean</td><td><code>true</code></td></tr><tr><td><code>show_branding</code></td><td>boolean</td><td><code>true</code></td></tr></tbody></table><h2 id="nodes" tabindex="-1">Nodes <a class="header-anchor" href="#nodes" aria-label="Permalink to &quot;Nodes&quot;">​</a></h2><p>Aerini has no separate top-level list for triggers. Manual Trigger, Schedule, and Webhook are ordinary entries in <code>nodes</code>, identified by the <code>node_type_id</code> values <code>manual_trigger</code>, <code>schedule</code>, and <code>webhook</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default / notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Yes</td><td>Unique within this workflow, e.g. <code>&quot;node_abc123&quot;</code>.</td></tr><tr><td><code>node_type_id</code></td><td>string</td><td>Yes</td><td>Which node implementation to run, e.g. <code>&quot;http_request&quot;</code>. See <a href="./../guide/nodes">Nodes Reference</a> for every valid value.</td></tr><tr><td><code>node_type</code></td><td>string</td><td>Yes</td><td>One of <code>&quot;action&quot;</code>, <code>&quot;ai&quot;</code>, <code>&quot;logic&quot;</code>, <code>&quot;utility&quot;</code>. Controls which palette section the node appears in; has no effect on execution.</td></tr><tr><td><code>name</code></td><td>string</td><td>Yes</td><td>Label shown on the canvas block.</td></tr><tr><td><code>config</code></td><td>object</td><td>No</td><td>Defaults to <code>{}</code>. Node-specific settings from the config panel; shape depends entirely on <code>node_type_id</code>, see <a href="./../guide/nodes">Nodes Reference</a>.</td></tr><tr><td><code>credentials</code></td><td>object</td><td>No</td><td>Defaults to <code>{}</code>. Maps a config field name to a saved credential&#39;s ID, e.g. <code>{&quot;api_key&quot;: &quot;openai-prod&quot;}</code>. The secret itself never appears in this file, see <a href="./../guide/credentials">Credentials</a>.</td></tr><tr><td><code>input_schema</code></td><td>object</td><td>Yes</td><td>JSON Schema the node&#39;s input must match. The app always writes <code>{}</code> for a node with no schema of its own; the key still has to be present.</td></tr><tr><td><code>output_schema</code></td><td>object</td><td>Yes</td><td>Same rule as <code>input_schema</code>, for the node&#39;s output.</td></tr><tr><td><code>retry</code></td><td>object</td><td>No</td><td>Defaults to one attempt, no automatic retry, see <a href="#retry">Retry</a> below.</td></tr><tr><td><code>fallback_node</code></td><td>string or <code>null</code></td><td>No</td><td>Reserved for future use. Not read by the executor in the current version.</td></tr><tr><td><code>disabled</code></td><td>boolean</td><td>No</td><td>Defaults to <code>false</code>. When <code>true</code>, the executor skips the node and treats it as if it succeeded with empty output.</td></tr><tr><td><code>position</code></td><td>object</td><td>No</td><td>Defaults to <code>{&quot;x&quot;: 0, &quot;y&quot;: 0}</code>. Canvas coordinates, <code>{&quot;x&quot;: number, &quot;y&quot;: number}</code>, ignored by the executor.</td></tr></tbody></table><p>The desktop app also writes <code>ports</code> and <code>dynamic_ports</code> into every saved node object, canvas metadata it uses to draw connection points. Neither is read by the engine; a file that leaves them out loads fine.</p><p>A number, integer or true-or-false config field may hold a string that is a single <code>{{...}}</code> reference. The engine converts the resolved text to the field&#39;s type before the node runs. Older builds keep the string as is, so the node falls back to that field&#39;s default.</p><h3 id="retry" tabindex="-1">Retry <a class="header-anchor" href="#retry" aria-label="Permalink to &quot;Retry&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>max_attempts</code></td><td>number</td><td><code>1</code></td></tr><tr><td><code>backoff_ms</code></td><td>number</td><td><code>500</code></td></tr></tbody></table><p><code>max_attempts: 1</code> means no automatic retry. A node with side effects, an email send or an HTTP POST, only retries on its own if a workflow author raises this above 1 from the Retry UI.</p><p>The engine clamps <code>max_attempts</code> to between 1 and 10 when it runs a node, and the Tries field (under Advanced) in the desktop app stops at 10 to match.</p><h2 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h2><p>A connection is the line drawn from one node&#39;s output to another&#39;s input; the JSON key for the array holding them is <code>edges</code>, and each entry below is one connection.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default / notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Yes</td><td>Unique ID for this connection.</td></tr><tr><td><code>from_node</code></td><td>string</td><td>Yes</td><td>Source node&#39;s <code>id</code>.</td></tr><tr><td><code>from_port</code></td><td>string</td><td>Yes</td><td>Output port name on the source node, e.g. <code>&quot;output&quot;</code>, or a branch name such as <code>&quot;on_true&quot;</code> for a node with more than one output.</td></tr><tr><td><code>to_node</code></td><td>string</td><td>Yes</td><td>Target node&#39;s <code>id</code>.</td></tr><tr><td><code>to_port</code></td><td>string</td><td>Yes</td><td>Input port name on the target node, e.g. <code>&quot;input&quot;</code>. At most one connection may end on a given input port unless that port is multi-input; see <a href="#input-port-arity">Input port arity</a>.</td></tr><tr><td><code>condition</code></td><td>string or <code>null</code></td><td>No</td><td>Expression the canvas uses to decide whether to draw the line. Not evaluated by the executor: routing follows <code>from_port</code> alone.</td></tr><tr><td><code>on_success</code></td><td>string or <code>null</code></td><td>No</td><td>Alternate target node ID activated when the source node succeeds, used to register an extra reachability edge.</td></tr><tr><td><code>on_failure</code></td><td>string or <code>null</code></td><td>No</td><td>Target node ID the executor routes to when the source node fails after every retry attempt, instead of aborting the run. The target runs only when the route fires, after the source node, and does not need a connection from it. It cannot be a node that runs before the source: that is a cycle and the run fails with <code>CycleDetected</code>.</td></tr></tbody></table><h3 id="input-port-arity" tabindex="-1">Input port arity <a class="header-anchor" href="#input-port-arity" aria-label="Permalink to &quot;Input port arity&quot;">​</a></h3><p>An input port accepts one connection unless its node type declares it multi-input; Merge&#39;s input is the only built-in one. Any number of connections may leave an output port. A node type marks a multi-input port with <code>&quot;arity&quot;: &quot;multi&quot;</code> on the port in its descriptor; ports without <code>arity</code> accept one connection. The desktop app copies descriptor ports into each saved node&#39;s <code>ports</code>, but the engine reads arity from the node type, not from the file.</p><p>Before any node runs, the engine rejects a workflow that puts two or more connections on a single-input port and returns <code>PortArityViolation</code>: <code>Input port &#39;input&#39; on node &#39;n_c&#39; accepts one connection but has 2; remove the extra wires or route them through a Merge node</code>. Only the first violation, in <code>edges</code> order, is reported. The desktop app opens such a file with every connection intact, marks the port in red, and warns once; Run then fails with the error above.</p><h2 id="schema-version" tabindex="-1">Schema version <a class="header-anchor" href="#schema-version" aria-label="Permalink to &quot;Schema version&quot;">​</a></h2><p>Every workflow file carries a <code>schema_version</code> field so whatever loads it knows which shape to expect. As of Aerini 0.4.0 the format hasn&#39;t changed since it was introduced, so this is <code>&quot;1.0&quot;</code> everywhere and there is nothing to migrate yet. A file with no <code>schema_version</code> field at all, saved before the field existed, is treated as the oldest version this build knows and loads normally.</p><p>What happens for a version that&#39;s older, newer, or otherwise mismatched, and what runs when a migration path actually exists, is covered in <a href="./../operations/updating#opening-older-or-newer-workflow-files">Updating §Opening older or newer workflow files</a> rather than repeated here. A version-by-version history of format changes will live in <code>schema-migrations.md</code> once there is more than one version to show.</p><h2 id="aerini-server-s-exported-config" tabindex="-1">aerini-server&#39;s exported config <a class="header-anchor" href="#aerini-server-s-exported-config" aria-label="Permalink to &quot;aerini-server&#39;s exported config&quot;">​</a></h2><p>Choosing <strong>Export → Export for Server</strong> writes a config file, <code>aerini-server.json</code>, whose <code>workflow_json</code> field holds this exact schema, unmodified, as a JSON string, the same shape the desktop app already has saved to its own database. <code>aerini-server serve</code> reads that file and loads the workflow the same way the desktop app does. See <a href="./../operations/server-deploy">Server Deployment</a> and <a href="./../operations/server-cli-reference#serve">Server CLI Reference</a> for the rest of that config file and the flags around it.</p><h2 id="what-export-writes" tabindex="-1">What Export writes <a class="header-anchor" href="#what-export-writes" aria-label="Permalink to &quot;What Export writes&quot;">​</a></h2><p><strong>Export → Export workflow</strong> and <strong>Export → Export All</strong> write this same schema, field for field, with one deliberate exception: <code>metadata.collection_id</code> is always written as <code>null</code>. Collection membership is this sidebar&#39;s local folder organization, not a portable property of the workflow itself, so it never leaves the app through an exported file.</p><p>Everything else, including <code>parallel_execution</code>, <code>unlimited_duration</code>, <code>max_concurrent_nodes</code>, <code>settings</code>, and the rest of <code>metadata</code>, is written exactly as it stands in the workflow being exported, omitted only where <a href="#top-level-fields">Top-level fields</a> above already says the native format omits an at-default field. Re-importing an exported file restores all of it; the workflow lands in Uncategorized, since collection membership is the one thing an export never carries.</p><p>A <code>.json</code> file works the same as a <code>.aerini</code> file here too, see <a href="./../glossary#workflow-file">Workflow file</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="./../getting-started/concepts">Concepts</a>, for what a workflow, node, and connection are before reading their JSON shape</li><li><a href="./../guide/nodes">Nodes Reference</a>, for what belongs inside a given node type&#39;s <code>config</code></li><li><a href="./../guide/credentials">Credentials</a>, for how the <code>credentials</code> map resolves to a real secret at run time</li><li><code>schema-migrations.md</code>, for a version-by-version history once the format has more than one version to show</li></ul>',46)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
